.workspace-loading-overlay__badge--remote {
    border-color: rgba(105, 195, 255, 0.34);
    background: rgba(83, 158, 255, 0.12);
    color: rgba(202, 230, 255, 1);
}

.workspace-loading-overlay__phase,
.workspace-loading-overlay__detail,
.workspace-loading-overlay__progress-copy {
    margin: 0;
}

.workspace-loading-overlay__phase {
    font-size: 1rem;
    font-weight: 560;
    color: var(--app-body-color, var(--mat-sys-on-surface));
}

.workspace-loading-overlay__detail {
    max-width: 32ch;
    justify-self: center;
    color: var(--app-muted-color, var(--mat-sys-on-surface-variant));
    line-height: 1.45;
}

.workspace-loading-overlay__progress-copy {
    font-variant-numeric: tabular-nums;
    color: var(--app-muted-color, var(--mat-sys-on-surface-variant));
}

.workspace-loading-overlay__action {
    justify-self: center;
    min-width: 180px;
    border-radius: 999px;
}

:host ::ng-deep .workspace-loading-overlay__card .mat-mdc-progress-bar {
    overflow: hidden;
    border-radius: 999px;
}

@keyframes workspace-loading-overlay-enter {
    from {
        opacity: 0;
        transform: translateY(10px) scale(0.985);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

:host ::ng-deep .workspace-command-palette-overlay .mat-mdc-dialog-surface {
    background: transparent;
    box-shadow: none;
    overflow: visible;
    border-radius: 14px;
    padding: 0;
}

@media (max-width: 780px) {
    .workspace-shell {
        grid-template-columns: 56px 1fr;
        grid-template-rows: 56px 1fr auto;
    }
}

@media (max-width: 640px) {
    .workspace-shell {
        grid-template-columns: 1fr;
        grid-template-rows: 52px 56px minmax(0, 1fr) auto;
    }

    app-workspace-shell-rail {
        grid-column: 1;
        grid-row: 1;
    }

    app-workspace-shell-header {
        grid-column: 1;
        grid-row: 2;
    }

    .workspace-body {
        grid-column: 1;
        grid-row: 3;
    }

    .workspace-now-playing {
        grid-column: 1;
        grid-row: 4;
    }
}

input.command:
sleep 3 && agent-browser --cdp 9222 key "Escape" && sleep 1 && agent-browser --cdp 9222 key "Meta+k" && sleep 1 && agent-browser --cdp 9222 eval "(() => {
  const s = document.querySelector('.mat-mdc-dialog-surface');
  const cs = getComputedStyle(s);
  return JSON.stringify({bg: cs.backgroundColor, radius: cs.borderRadius, overflow: cs.overflow, padding: cs.padding});
})()" && agent-browser --cdp 9222 screenshot /tmp/iptvnator-palette-final.png
